public void testAccessorFormalRetainedUnderUnusedCleanup() {
  CompilerOptions options = createCompilerOptions();
  options.setLanguageIn(LanguageMode.ECMASCRIPT5);
  options.removeUnusedVars = true;
  options.removeUnusedLocalVars = true;
  String code = ""
      + "var host = {set level(value) { window.flag = 1; }};"
      + "var probe = {plain: function(unusedFormal) { window.flag = 2; }};"
      + "window.host = host; window.probe = probe;";
  test(options, code, ""
      + "var host = {set level(value) { window.flag = 1; }};"
      + "var probe = {plain: function() { window.flag = 2; }};"
      + "window.host = host; window.probe = probe;");
}
